import SwiftUI
import WatchConnectivity

@main
struct EOVWatchCompanionApp: App {
    @StateObject private var store = EOVWatchCompanionStore()
    var body: some Scene {
        WindowGroup {
            NavigationStack { CurrentRunScreen() }.environmentObject(store)
                .task {
                    try? await Task.sleep(for: .seconds(8))
                    NSLog("[EOVWatchBoundary] invoking refresh activation=%d reachable=%d", WCSession.default.activationState.rawValue, WCSession.default.isReachable)
                    store.refresh()
                    NSLog("[EOVWatchBoundary] refresh status=%@", store.message)
                }
        }
    }
}
